```python
def is_bst(root):
    def valid(node, min_val, max_val):
        if node is None:
            return True
        if not (min_val <= node.val <= max_val):
            return False
        return (valid(node.left, min_val, node.val) and
                valid(node.right, node.val, max_val))
    return valid(root, float('-inf'), float('inf'))
```

