def is_valid(s):
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    for ch in s:
        if ch in pairs:
            top = stack.pop() if stack else '#'
            if pairs[ch] != top:
                return False
        else:
            stack.append(ch)
    return not stack
