def permutations(n):
    nums = list(range(1, n + 1))
    return _permute(nums)

def _permute(nums):
    if not nums:
        return [[]]
    result = []
    for i, x in enumerate(nums):
        for perm in _permute(nums[:i] + nums[i+1:]):
            result.append([x] + perm)
    return result
