def remove_duplicates(head):
    if head is None:
        return None
    seen = set()
    node = head
    prev = None
    while node:
        if node.data in seen:
            prev.next = node.next
        else:
            seen.add(node.data)
            prev = node
        node = node.next
    return head
```

